    }
    */

    @Test
    public void testNextTextValue_NullsBinaryValue() throws Exception {
        // The first line of the method is _binaryValue = null;
        // This test ensures no exception is thrown during the null assignment
        setField("_nextToken", JsonToken.VALUE_STRING);
        setField("_currText", "test");

        parser.nextTextValue();

        Field binaryField = FromXmlParser.class.getDeclaredField("_binaryValue");
        binaryField.setAccessible(true);
        assertNull(binaryField.get(parser));
    }
}
